def _permissions_for(path: str, method: str):
    route = next(r for r in router.routes if r.path == path and method in r.methods)
    return [
        permission
        for dependency in route.dependencies
        if isinstance(dependency.dependency, PermissionsDependency)
        for permission in dependency.dependency.permissions
    ]


